FPotionRow UDocShowcaseLibrary::GetPotionRow(int32 Key, bool& bFound)
{
    const FPotionRow* Found = FDocShowcase::Potion().FindByIndex(Key);

    bFound = Found != nullptr;

    // A copy, because Blueprint takes a struct by value and the row belongs to the table.
    // A default one when the key is not there, which is why bFound is not decoration.
    return Found != nullptr ? *Found : FPotionRow();
}

int32 UDocShowcaseLibrary::GetPotionRowCount()
{
    return FDocShowcase::Potion().Records().Num();
}

FPotionRow UDocShowcaseLibrary::GetPotionRowAt(int32 Position, bool& bFound)
{
    const TArray<FPotionRow>& Rows = FDocShowcase::Potion().Records();

    bFound = Rows.IsValidIndex(Position);

    return bFound ? Rows[Position] : FPotionRow();
}


