bool UDocShowcaseLibrary::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    return FDocShowcase::ReadAll(BasePath, FileExtension);
}

bool FDocShowcase::ReadAll(const FString& BasePath, const FString& FileExtension)
{
    // Read into tables of their own and moved into place at the end. Reading again is a
    // refresh - a patched .pak, a downloaded table - and one that fails on the third file
    // must not leave the first two replaced and the rest as they were.
    FPotionTable LoadedPotion;

    if (!LoadedPotion.Read(FPaths::Combine(BasePath, TEXT("Potion") + FileExtension)))
    {
        return false;
    }
    FShopTable LoadedShop;

    if (!LoadedShop.Read(FPaths::Combine(BasePath, TEXT("Shop") + FileExtension)))
    {
        return false;
    }
    FShopEntryTable LoadedShopEntry;

    if (!LoadedShopEntry.Read(FPaths::Combine(BasePath, TEXT("ShopEntry") + FileExtension)))
    {
        return false;
    }
    FLootTable LoadedLoot;

    if (!LoadedLoot.Read(FPaths::Combine(BasePath, TEXT("Loot") + FileExtension)))
    {
        return false;
    }
    FSpawnTable LoadedSpawn;

    if (!LoadedSpawn.Read(FPaths::Combine(BasePath, TEXT("Spawn") + FileExtension)))
    {
        return false;
    }
    FStageRewardTable LoadedStageReward;

    if (!LoadedStageReward.Read(FPaths::Combine(BasePath, TEXT("StageReward") + FileExtension)))
    {
        return false;
    }

    PotionStorage = MoveTemp(LoadedPotion);
    ShopStorage = MoveTemp(LoadedShop);
    ShopEntryStorage = MoveTemp(LoadedShopEntry);
    LootStorage = MoveTemp(LoadedLoot);
    SpawnStorage = MoveTemp(LoadedSpawn);
    StageRewardStorage = MoveTemp(LoadedStageReward);

    return true;
}
